def encode(message):
    vowels = 'aeiouAEIOU'
    encoded = []

    for char in message:
        if char in vowels:
            new_char = chr(ord(char) + 2)
            encoded.append(new_char)
        elif char.isalpha():
            if char.islower():
                encoded.append(char.upper())
            else:
                encoded.append(char.lower())
        else:
            encoded.append(char)

    return ''.join(encoded)
